INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l48','cut off from','',NULL,'/kʌt ɔːf frəm/','The village was cut off from the world.','那村子与世隔绝。','We were cut off from all news.','我们与一切消息隔绝。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l48','descend on','',NULL,'/dɪˈsend ɑːn/','Busloads of tourists descended on the town.','一车车游客涌进了小镇。','Reporters descended on the movie star.','记者们蜂拥到那位影星身边。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l48','come to life','',NULL,'/kʌm tə laɪf/','The silent village suddenly came to life.','沉默的村子忽然活了起来。','The party came to life after midnight.','派对午夜后热闹起来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l48','quicken one''s pace','',NULL,'/ˈkwɪkən wʌnz peɪs/','We quickened our pace toward the stream.','我们加快脚步朝溪边走去。','She quickened her pace as it grew dark.','天渐渐黑了,她加快了脚步。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp1','choice','{"stem":"\"The village seemed deserted, the only sign of life ___ a black goat.\"(独立主格:名词 + ___ + 名词,填 be 动词的 -ing 形式)","options":["was","being","is","been"],"answer_index":1,"stem_cn":"村子似乎无人居住,唯一的生命迹象是一只黑山羊。","explanation_cn":"独立主格结构:名词 + 分词作状语;sign 与 be 是主动同时关系,用现在分词 being。✓ the only sign of life being a black goat. ✗ was / is(独立主格不用限定动词)/ been(需与 have 连用)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp1','choice','{"stem":"\"The meal ___, we walked on toward the stream.\"(独立主格:名词 + 过去分词,表完成“…结束后”)","options":["finished","finish","finishes","finishing"],"answer_index":0,"stem_cn":"饭吃完后,我们朝溪边走去。","explanation_cn":"独立主格:名词 + 过去分词,表被动/完成“…结束后”;meal 被吃完,用 finished。✓ The meal finished, we walked on. ✗ finishing / finish / finishes:表完成用过去分词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp1','choice','{"stem":"\"The children watched us, their eyes ___ on our food.\"(独立主格:名词 + 过去分词,“盯在…上”)","options":["fixing","fixed","to fix","fix"],"answer_index":1,"stem_cn":"孩子们看着我们,目光盯在我们的食物上。","explanation_cn":"独立主格:名词 + 过去分词,eyes 与 fix 是被动“被固定、盯住”,用 fixed。✓ their eyes fixed on our food. ✗ fixing / fix / to fix:表被动用过去分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp2','choice','{"stem":"\"___ a path that led out of town, we crossed a few fields.\"(现在分词短语作状语:走上一条…)","options":["To take","Take","Taken","Taking"],"answer_index":3,"stem_cn":"走上一条出镇的小路,我们穿过几块农田。","explanation_cn":"现在分词短语作状语,逻辑主语是主句的 we;主动“走上一条路”用 Taking。✓ Taking a path …, we crossed fields. ✗ Taken(被动)/ Take / To take:主动作状语用 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp2','choice','{"stem":"\"___ up, I saw children surrounding us.\"(现在分词短语作状语:抬头一看)","options":["To look","Look","Looking","Looked"],"answer_index":2,"stem_cn":"抬头一看,我发现孩子们围住了我们。","explanation_cn":"现在分词短语作状语,逻辑主语是 I;主动“抬头看”用 Looking。✓ Looking up, I saw … ✗ Looked / Look / To look:主动伴随用 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp2','choice','{"stem":"\"___ back down the street, we quickened our pace.\"(现在分词短语作状语:转身往回走)","options":["Turned","Turning","To turn","Turn"],"answer_index":1,"stem_cn":"转身沿街往回走,我们加快了脚步。","explanation_cn":"现在分词短语作状语,逻辑主语是 we;主动“转身”用 Turning。✓ Turning back …, we quickened our pace. ✗ Turned / Turn / To turn:主动用 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp3','choice','{"stem":"\"We took a path ___ led out of the town.\"(定语从句,先行词是物,在从句中作主要成分)","options":["which","whom","what","who"],"answer_index":0,"stem_cn":"我们走上一条通向镇外的小路。","explanation_cn":"定语从句先行词 path 是物,关系词在从句中作主要成分,用 which。✓ a path which led out of the town. ✗ who(指人)/ whom(宾格)/ what(不引导定语从句)。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp3','choice','{"stem":"\"We were watched by children ___ were dressed in rags.\"(定语从句,先行词是人,在从句中作主要成分)","options":["whom","which","who","what"],"answer_index":2,"stem_cn":"我们被一群穿着破衣的孩子注视着。","explanation_cn":"定语从句先行词 children 是人,关系词作主要成分,用 who。✓ children who were dressed in rags. ✗ which(指物)/ whom(此处作主要成分不用宾格)/ what。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp3','choice','{"stem":"\"The village, ___ had seemed deserted, suddenly came to life.\"(非限定定语从句,先行词是物)","options":["which","who","what","that"],"answer_index":0,"stem_cn":"那个原本似乎空无一人的村子,忽然活了起来。","explanation_cn":"非限定定语从句(有逗号),先行词是物,只能用 which,不用 that。✓ The village, which had seemed deserted, … ✗ that(非限定不用)/ who(指人)/ what。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp4','choice','{"stem":"\"They were cut off not only from tourists ___ even from their own countrymen.\"(not only … ___ even …:不但…甚至…)","options":["or","but","and","nor"],"answer_index":1,"stem_cn":"他们不但与游客隔绝,甚至与本国同胞隔绝。","explanation_cn":"not only … but even …,“不但…甚至…”;连接用 but。✓ not only from tourists but even from countrymen. ✗ and / or / nor:与 not only 搭配用 but。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp4','choice','{"stem":"\"Thousands of places are still inaccessible ___ tourists.\"(be inaccessible ___:难以到达,填介词)","options":["of","with","to","for"],"answer_index":2,"stem_cn":"仍有成千上万的地方游客难以到达。","explanation_cn":"be inaccessible to sb,“对…难以到达”;固定介词 to。✓ inaccessible to tourists. ✗ for / of / with:inaccessible 搭配 to。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp4','choice','{"stem":"\"The village was completely cut off ___ the outside world.\"(be cut off ___:与…隔绝,填介词)","options":["to","from","with","of"],"answer_index":1,"stem_cn":"那村子与外界完全隔绝。","explanation_cn":"be cut off from,“与…隔绝”;固定介词 from。✓ cut off from the outside world. ✗ of / to / with:cut off 搭配 from。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp5','choice','{"stem":"\"In the boat there was a boatman fast ___.\"(形容词短语后置修饰 boatman:熟睡的)","options":["sleep","sleeps","to sleep","asleep"],"answer_index":3,"stem_cn":"船上有个熟睡的船夫。","explanation_cn":"形容词短语 fast asleep 放名词后修饰它,“熟睡的”;asleep 是表状态的形容词。✓ a boatman fast asleep. ✗ sleep / sleeps / to sleep:此处需形容词 asleep。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp5','choice','{"stem":"\"The houses ___ of gray mud bricks looked forbidding.\"(过去分词后置修饰 houses:用…建成的)","options":["building","built","build","to build"],"answer_index":1,"stem_cn":"用灰色土坯建成的房子看着让人发怵。","explanation_cn":"过去分词短语放名词后修饰它,表被动“被建成”。✓ houses built of gray mud bricks. ✗ building(主动)/ build / to build:表被动用过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp5','choice','{"stem":"\"We were surrounded by children ___ in rags.\"(过去分词后置修饰 children:穿着破衣的)","options":["dress","to dress","dressing","dressed"],"answer_index":3,"stem_cn":"我们被一群衣衫褴褛的孩子围住。","explanation_cn":"过去分词放名词后修饰 children,表被动/状态“穿着…的”。✓ children dressed in rags. ✗ dressing / dress / to dress:表状态用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp6','choice','{"stem":"\"A building that is old, broken and falling apart is ___.\"(“陈旧破烂的、倒塌的”用哪个词)","options":["brand-new","dilapidated","sturdy","modern"],"answer_index":1,"stem_cn":"又旧又破、快要坍塌的建筑。","explanation_cn":"又旧又破、快要坍塌是 dilapidated。✓ a dilapidated wooden fence. ✗ brand-new 崭新;✗ modern 现代;✗ sturdy 结实——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp6','choice','{"stem":"\"Someone standing completely still, not moving at all, is ___.\"(“不动的”用哪个词)","options":["motionless","restless","cheerful","busy"],"answer_index":0,"stem_cn":"一动不动地站着的。","explanation_cn":"一动不动是 motionless。✓ they remained motionless. ✗ restless 焦躁;✗ cheerful 欢快;✗ busy 忙碌——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',5,'am3_l48_gp6','choice','{"stem":"\"To stare hard at something to see it better is to ___.\"(“凝视、盯着”用哪个词)","options":["shout","wave","ignore","peer"],"answer_index":3,"stem_cn":"眯眼凝视、盯着看。","explanation_cn":"眯眼凝视、盯着看是 peer。✓ old women peered at us. ✗ shout 喊叫;✗ wave 挥手;✗ ignore 无视——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',6,NULL,'choice','{"stem":"inaccessible 的意思是:","options":["古老的","宽敞的","好客的","难接近的,达不到的"],"answer_index":3,"explanation_cn":"inaccessible = 难接近的、达不到的。✓ places inaccessible to tourists 游客难以到达的地方。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',6,NULL,'choice','{"stem":"hostile 的意思是:","options":["不友好的,有敌意的","慷慨的","热情好客的","害羞的"],"answer_index":0,"explanation_cn":"hostile = 不友好的、有敌意的。✓ hostile to travelers 对旅行者不友好。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',6,NULL,'choice','{"stem":"dilapidated 的意思是:","options":["宽敞的","陈旧破烂的,倒塌的","崭新的","明亮的"],"answer_index":1,"explanation_cn":"dilapidated = 陈旧破烂的、倒塌的。✓ a dilapidated wooden fence 一堵歪斜破旧的木栅栏。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',6,NULL,'choice','{"stem":"motionless 的意思是:","options":["吵闹的","快速的","不动的","柔软的"],"answer_index":2,"explanation_cn":"motionless = 不动的。✓ they remained motionless 他们一动不动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',6,NULL,'choice','{"stem":"procession 的意思是:","options":["山谷","行列,成队的人群","空地","寂静"],"answer_index":1,"explanation_cn":"procession = 行列、成队的人群。✓ a silent procession of children 一队沉默的孩子。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',6,NULL,'choice','{"stem":"peer 的意思是:","options":["凝视,盯着","挥手","低语","微笑"],"answer_index":0,"explanation_cn":"peer = 凝视、盯着。✓ old women peered at us 老妇人凝视我们。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',7,NULL,'cloze','{"stem":"第 1 空","context":"In this much-traveled world, there are still places that are inaccessible ___1___ tourists. People who are cut off ___2___ the outside world can be wary of strangers. Taking a path ___3___ led out of the town, my wife and I reached a silent village. The place seemed deserted, the only sign of life ___4___ a black goat tied to a tree.","blank_no":1,"options":["to","for","of","with"],"answer_index":0,"explanation_cn":"be inaccessible to,“对…难以到达”。✓ inaccessible to tourists."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',7,NULL,'cloze','{"stem":"第 2 空","context":"In this much-traveled world, there are still places that are inaccessible ___1___ tourists. People who are cut off ___2___ the outside world can be wary of strangers. Taking a path ___3___ led out of the town, my wife and I reached a silent village. The place seemed deserted, the only sign of life ___4___ a black goat tied to a tree.","blank_no":2,"options":["from","of","to","with"],"answer_index":0,"explanation_cn":"be cut off from,“与…隔绝”。✓ cut off from the outside world."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',7,NULL,'cloze','{"stem":"第 3 空","context":"In this much-traveled world, there are still places that are inaccessible ___1___ tourists. People who are cut off ___2___ the outside world can be wary of strangers. Taking a path ___3___ led out of the town, my wife and I reached a silent village. The place seemed deserted, the only sign of life ___4___ a black goat tied to a tree.","blank_no":3,"options":["which","who","what","whose"],"answer_index":0,"explanation_cn":"定语从句先行词 path 是物,用 which。✓ a path which led out of the town."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',7,NULL,'cloze','{"stem":"第 4 空","context":"In this much-traveled world, there are still places that are inaccessible ___1___ tourists. People who are cut off ___2___ the outside world can be wary of strangers. Taking a path ___3___ led out of the town, my wife and I reached a silent village. The place seemed deserted, the only sign of life ___4___ a black goat tied to a tree.","blank_no":4,"options":["being","was","is","been"],"answer_index":0,"explanation_cn":"独立主格:名词 + being,“唯一的生命迹象是…”。✓ the only sign of life being a black goat."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',8,NULL,'choice','{"stem":"Why was the village silent?","options":["A festival had emptied the streets","The village had been abandoned","Everyone was fast asleep","The villagers were wary of strangers and did not welcome the visitors"],"answer_index":3,"explanation_cn":"录音说与外界隔绝的村民对陌生人心存戒备,不欢迎来客,所以村子一片沉默。✓ wary, unwelcoming."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',8,NULL,'choice','{"stem":"How did the couple cross the deep stream?","options":["They walked around it","They built a raft","A boatman ferried them across in his boat","They swam across"],"answer_index":2,"explanation_cn":"录音说他们叫醒岸边小船上熟睡的船夫,请他把他们摆渡过溪。✓ a boatman ferried them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',8,NULL,'choice','{"stem":"What did the couple do when they realized they were unwelcome?","options":["They shouted at the villagers","They quickened their pace and hurried back toward the stream","They knocked on a door for help","They set up camp for the night"],"answer_index":1,"explanation_cn":"录音说意识到不受欢迎后,他们转身加快脚步,匆匆返回溪边。✓ quickened their pace back to the stream."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',9,NULL,'choice','{"stem":"你想说\"村子似乎无人居住,唯一的生命迹象是一只黑山羊\"(独立主格):","options":["The village seemed deserted, the only sign of life been a black goat.","The village seemed deserted, the only sign of life being a black goat.","The village seemed deserted, the only sign of life was a black goat being.","The village seemed deserted, the only sign of life be a black goat."],"answer_index":1,"explanation_cn":"独立主格用名词 + being + 名词;being 不能换成 was/be/been,也不能放句尾。✓ the only sign of life being a black goat. 场合:补充说明主句情况。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',9,NULL,'choice','{"stem":"你想说\"抬头一看,我发现孩子们围住了我们\"(现在分词状语):","options":["To look up, I saw that we were surrounded by children.","Look up, I saw that we were surrounded by children.","Looked up, I saw that we were surrounded by children.","Looking up, I saw that we were surrounded by children."],"answer_index":3,"explanation_cn":"现在分词作状语,动作的发出者须与主句里的 I 一致;用主动 Looking,不用 Looked/Look/To look。✓ Looking up, I saw … 场合:表达“…时,我…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',9,NULL,'choice','{"stem":"你想说\"他们不但与游客隔绝,甚至与本国同胞隔绝\"(not only … but even …):","options":["They were cut off not only from tourists but even from their own countrymen.","They were cut off not only from tourists but even their own countrymen from.","They were cut off not only from tourists and even from their own countrymen.","They were cut off not only tourists but even from their own countrymen."],"answer_index":0,"explanation_cn":"not only … but even …,but 后要重复介词 from、且语序为 but even from …。✓ not only from tourists but even from their own countrymen. 场合:表达“不但…甚至…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"hostile 的意思是:","options":["热情好客的","慷慨的","不友好的,有敌意的","害羞的"],"answer_index":2,"explanation_cn":"hostile = 不友好的、有敌意的。✓ hostile to travelers."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"dilapidated 的意思是:","options":["陈旧破烂的,倒塌的","宽敞的","明亮的","崭新的"],"answer_index":0,"explanation_cn":"dilapidated = 陈旧破烂的、倒塌的。✓ a dilapidated wooden fence."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"\"The village seemed deserted, the only sign of life ___ a black goat.\"(独立主格:名词 + ___ + 名词)","options":["was","is","been","being"],"answer_index":3,"stem_cn":"村子似乎无人居住,唯一的生命迹象是一只黑山羊。","explanation_cn":"独立主格:名词 + being + 名词。✓ the only sign of life being a black goat. ✗ was / is / been。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"\"___ a path that led out of town, we crossed a few fields.\"(现在分词短语作状语)","options":["Taking","Take","To take","Taken"],"answer_index":0,"stem_cn":"走上一条出镇的小路,我们穿过几块农田。","explanation_cn":"现在分词短语作状语,主动用 Taking。✓ Taking a path …, we crossed fields. ✗ Taken / Take / To take。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"\"cut off from\" 的意思是:","options":["依赖…","靠近…","与…隔绝","加入…"],"answer_index":2,"explanation_cn":"cut off from = 与…隔绝。✓ cut off from the outside world 与外界隔绝。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"\"come to life\" 的意思是:","options":["苏醒过来、活跃起来","保持安静","陷入沉睡","突然消失"],"answer_index":0,"explanation_cn":"come to life = 苏醒过来、活跃起来。✓ the village came to life 村子活了起来。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"Why did the couple decide to explore the countryside on their last day?","options":["Their hotel was full","The churches were all closed","Busloads of tourists had descended on the town","They had lost their way"],"answer_index":2,"passage":"In this much-traveled world, there are still thousands of places that are inaccessible to tourists. We always assume that villagers in remote places are friendly and hospitable. But people who are cut off not only from foreign tourists, but even from their own countrymen, can be wary of strangers. Visits to really remote villages are seldom relaxing — as my wife and I discovered during a trip through the Balkans. We had spent several days in a small town and visited a number of old churches nearby. These attracted many visitors, for they were not only of great architectural interest but also contained a large number of beautifully preserved frescoes. On the day before we left, several busloads of tourists descended on the town. This was more than we could bear, so we decided to spend our last day exploring the countryside. Taking a path that led out of the town, we crossed a few fields until we came to a dense wood. We expected the path to end abruptly, but we found that it wound its way through the trees. We tramped through the wood for over two hours until we arrived at a deep stream. We could see that the path continued on the other side, but we had no idea how to get across. Suddenly my wife spotted a boat moored to the bank. In it there was a boatman fast asleep. We gently woke him up and asked him to ferry us to the other side. Though he was reluctant to do so at first, we eventually persuaded him to take us. The path led to a tiny village perched on the steep sides of a mountain. The place consisted of a straggling dirt road lined on either side by small houses. Even under a clear blue sky, the village looked unwelcoming, for all the houses were built of gray mud bricks. The village seemed deserted, the only sign of life being a black goat tied to a tree in a field nearby. Sitting down on a dilapidated wooden fence near the field, we opened a couple of cans of sardines and had a picnic lunch. All at once, I noticed that my wife seemed uneasy. Looking up, I saw that we were surrounded by children in rags who were watching us silently as we ate. We offered them food and spoke to them kindly, but they remained motionless. I concluded that they were simply shy of strangers. When we later walked down the main street of the village, we were followed by a silent procession of children. The village, which had seemed deserted, immediately came to life. Faces appeared at windows. Men in shirtsleeves stood outside their houses and stared at us. Old women in dark shawls peered at us from doorways. The strangest thing of all was that not a sound could be heard. There was no doubt that we were unwelcome visitors. We needed no further hint. Turning back down the main street, we quickened our pace and made our way rapidly toward the stream, where we hoped the boatman was still waiting.","explanation_cn":"课文说离开前一天几辆满载游客的公共汽车涌进小镇,他们受不了,才决定去乡间。✓ busloads descended on the town."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"How did the village change when the couple walked down the main street?","options":["It stayed completely empty","It began to rain heavily","The villagers cheered and welcomed them","The deserted-looking village suddenly came to life, with faces at windows"],"answer_index":3,"passage":"In this much-traveled world, there are still thousands of places that are inaccessible to tourists. We always assume that villagers in remote places are friendly and hospitable. But people who are cut off not only from foreign tourists, but even from their own countrymen, can be wary of strangers. Visits to really remote villages are seldom relaxing — as my wife and I discovered during a trip through the Balkans. We had spent several days in a small town and visited a number of old churches nearby. These attracted many visitors, for they were not only of great architectural interest but also contained a large number of beautifully preserved frescoes. On the day before we left, several busloads of tourists descended on the town. This was more than we could bear, so we decided to spend our last day exploring the countryside. Taking a path that led out of the town, we crossed a few fields until we came to a dense wood. We expected the path to end abruptly, but we found that it wound its way through the trees. We tramped through the wood for over two hours until we arrived at a deep stream. We could see that the path continued on the other side, but we had no idea how to get across. Suddenly my wife spotted a boat moored to the bank. In it there was a boatman fast asleep. We gently woke him up and asked him to ferry us to the other side. Though he was reluctant to do so at first, we eventually persuaded him to take us. The path led to a tiny village perched on the steep sides of a mountain. The place consisted of a straggling dirt road lined on either side by small houses. Even under a clear blue sky, the village looked unwelcoming, for all the houses were built of gray mud bricks. The village seemed deserted, the only sign of life being a black goat tied to a tree in a field nearby. Sitting down on a dilapidated wooden fence near the field, we opened a couple of cans of sardines and had a picnic lunch. All at once, I noticed that my wife seemed uneasy. Looking up, I saw that we were surrounded by children in rags who were watching us silently as we ate. We offered them food and spoke to them kindly, but they remained motionless. I concluded that they were simply shy of strangers. When we later walked down the main street of the village, we were followed by a silent procession of children. The village, which had seemed deserted, immediately came to life. Faces appeared at windows. Men in shirtsleeves stood outside their houses and stared at us. Old women in dark shawls peered at us from doorways. The strangest thing of all was that not a sound could be heard. There was no doubt that we were unwelcome visitors. We needed no further hint. Turning back down the main street, we quickened our pace and made our way rapidly toward the stream, where we hoped the boatman was still waiting.","explanation_cn":"课文说他们沿大街走时,原本似乎空无一人的村子忽然活了起来,一张张脸出现在窗口。✓ came to life; faces at windows."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"What was the only sign of life when they first reached the village?","options":["A black goat tied to a tree","A ringing bell","A barking dog","Smoke from a chimney"],"answer_index":0,"audio":"In this much-traveled world, there are still thousands of places that are inaccessible to tourists. We always assume that villagers in remote places are friendly and hospitable. But people who are cut off not only from foreign tourists, but even from their own countrymen, can be wary of strangers. Visits to really remote villages are seldom relaxing — as my wife and I discovered during a trip through the Balkans. We had spent several days in a small town and visited a number of old churches nearby. These attracted many visitors, for they were not only of great architectural interest but also contained a large number of beautifully preserved frescoes. On the day before we left, several busloads of tourists descended on the town. This was more than we could bear, so we decided to spend our last day exploring the countryside. Taking a path that led out of the town, we crossed a few fields until we came to a dense wood. We expected the path to end abruptly, but we found that it wound its way through the trees. We tramped through the wood for over two hours until we arrived at a deep stream. We could see that the path continued on the other side, but we had no idea how to get across. Suddenly my wife spotted a boat moored to the bank. In it there was a boatman fast asleep. We gently woke him up and asked him to ferry us to the other side. Though he was reluctant to do so at first, we eventually persuaded him to take us. The path led to a tiny village perched on the steep sides of a mountain. The place consisted of a straggling dirt road lined on either side by small houses. Even under a clear blue sky, the village looked unwelcoming, for all the houses were built of gray mud bricks. The village seemed deserted, the only sign of life being a black goat tied to a tree in a field nearby. Sitting down on a dilapidated wooden fence near the field, we opened a couple of cans of sardines and had a picnic lunch. All at once, I noticed that my wife seemed uneasy. Looking up, I saw that we were surrounded by children in rags who were watching us silently as we ate. We offered them food and spoke to them kindly, but they remained motionless. I concluded that they were simply shy of strangers. When we later walked down the main street of the village, we were followed by a silent procession of children. The village, which had seemed deserted, immediately came to life. Faces appeared at windows. Men in shirtsleeves stood outside their houses and stared at us. Old women in dark shawls peered at us from doorways. The strangest thing of all was that not a sound could be heard. There was no doubt that we were unwelcome visitors. We needed no further hint. Turning back down the main street, we quickened our pace and made our way rapidly toward the stream, where we hoped the boatman was still waiting.","explanation_cn":"课文说村子似乎无人居住,唯一的生命迹象是拴在树上的一只黑山羊。✓ a black goat tied to a tree."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l48',10,NULL,'choice','{"stem":"How did the villagers look at the couple?","options":["With warm, welcoming smiles","With complete indifference","Silently and without moving, watching their every step","They offered them food and drink"],"answer_index":2,"audio":"In this much-traveled world, there are still thousands of places that are inaccessible to tourists. We always assume that villagers in remote places are friendly and hospitable. But people who are cut off not only from foreign tourists, but even from their own countrymen, can be wary of strangers. Visits to really remote villages are seldom relaxing — as my wife and I discovered during a trip through the Balkans. We had spent several days in a small town and visited a number of old churches nearby. These attracted many visitors, for they were not only of great architectural interest but also contained a large number of beautifully preserved frescoes. On the day before we left, several busloads of tourists descended on the town. This was more than we could bear, so we decided to spend our last day exploring the countryside. Taking a path that led out of the town, we crossed a few fields until we came to a dense wood. We expected the path to end abruptly, but we found that it wound its way through the trees. We tramped through the wood for over two hours until we arrived at a deep stream. We could see that the path continued on the other side, but we had no idea how to get across. Suddenly my wife spotted a boat moored to the bank. In it there was a boatman fast asleep. We gently woke him up and asked him to ferry us to the other side. Though he was reluctant to do so at first, we eventually persuaded him to take us. The path led to a tiny village perched on the steep sides of a mountain. The place consisted of a straggling dirt road lined on either side by small houses. Even under a clear blue sky, the village looked unwelcoming, for all the houses were built of gray mud bricks. The village seemed deserted, the only sign of life being a black goat tied to a tree in a field nearby. Sitting down on a dilapidated wooden fence near the field, we opened a couple of cans of sardines and had a picnic lunch. All at once, I noticed that my wife seemed uneasy. Looking up, I saw that we were surrounded by children in rags who were watching us silently as we ate. We offered them food and spoke to them kindly, but they remained motionless. I concluded that they were simply shy of strangers. When we later walked down the main street of the village, we were followed by a silent procession of children. The village, which had seemed deserted, immediately came to life. Faces appeared at windows. Men in shirtsleeves stood outside their houses and stared at us. Old women in dark shawls peered at us from doorways. The strangest thing of all was that not a sound could be heard. There was no doubt that we were unwelcome visitors. We needed no further hint. Turning back down the main street, we quickened our pace and made our way rapidly toward the stream, where we hoped the boatman was still waiting.","explanation_cn":"课文说村民默默注视、一动不动地看着他们,一点声音都听不见。✓ silent, motionless, watching."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
